  $j$[]$j$::jsonb, $j$[]$j$::jsonb, false);
with p as (insert into public.plantillas (codigo, nombre, descripcion, aplica_a, tipo_activo_id, frecuencia)
  values ('motobomba', 'Inspección de motobomba', '1 inspección = 1 motobomba, cada semana. 22 puntos Sí / No (16 antes y 6 durante la prueba) y 4 datos de la prueba funcional. Parte de «Inspección de bomba contra incendio».', 'activo', (select id from public.tipos_activo where empresa_id is null and codigo = 'motobomba'), 'semanal') returning id),
r as (select $j${"version":1,"firmas":[{"clave":"inspector","titulo":"Inspector","obligatoria":true,"externo":false,"minimo":1},{"clave":"custodia","titulo":"Responsable de la custodia del registro","obligatoria":true,"externo":false,"minimo":1}],"reglas":[{"tipo":"x_en","etiqueta":"No conforme","alcance":"todos"}],"resultado_defecto":"Conforme","puntaje":false,"na_favorable":true,"hallazgo_vencimiento":false,"observacion_general":true,"secciones":[{"clave":"antes","titulo":"ANTES DE LA PRUEBA","puntos":[{"clave":"MB-A01","texto":"[Motor] Nivel completo de aceite del motor","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A02","texto":"[Motor] Precalentador del refrigerante en funcionamiento","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A03","texto":"[Motor] Válvulas de refrigeración en posición abierta","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A04","texto":"[Tanque Combustible] Válvula de combustible en posición abierta","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A05","texto":"[Tanque Combustible] Nivel del tanque de combustible (Mayor a los 3/4 de la capacidad)","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A06","texto":"[Cisterna] Nivel de tanque de agua de la cisterna contra incendio se encuentra lleno","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A07","texto":"[Motor] Switches del tablero del motor Diesel en posición normal","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A08","texto":"[Tablero Principal] Selector del tablero de control principal se encuentre en AUTOMATICO","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A09","texto":"[Tablero Principal] Luces indicadoras de falla apagadas","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A10","texto":"[Bomba] Goteo normal de la prensaestopa de la bomba: aprox. 60 gotas por minuto","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A11","texto":"[Tablero Principal] Presion del sistema en el tablero de control (PSI) aprox. 150","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A12","texto":"[Motor] Voltajes de baterías del tablero del motor Diesel (Bat. 1; Bat. 2) aprox. 14 Voltios","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A13","texto":"[Tablero Principal] Voltajes de baterías del tablero principal (Bat. 1; Bat. 2) aprox. 14 Voltios","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A14","texto":"[Motor] Contómetro de horas del motor en funcionamiento","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A15","texto":"[Tablero Jockey] Selector de la bomba Jockey en automático","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-A16","texto":"[Tablero Principal] Nivel de tanque de combustible (> a los 3/4 de capacidad)","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false}]},{"clave":"durante","titulo":"DURANTE LA PRUEBA","puntos":[{"clave":"MB-B01","texto":"[N.A.] Hay flujo de agua a través del circuito de refrigeración. Si no lo hay \"APAGAR\"","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-B02","texto":"[N.A.] Funciona la presión en el tablero de control principal (PSI); Indicar PSI","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-B03","texto":"[N.A.] Funciona el tacómetro del motor Diesel (RPM); Indicar RPM","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-B04","texto":"[N.A.] Funciona el manómetro de presión de aceite del motor (PSI/Kpa)","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-B05","texto":"[N.A.] Funciona el manómetro de la presión del circuito de refrigeración (PSI); Indicar PSI","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-B06","texto":"[N.A.] Funciona el manómetro de temperatura del motor (°F/°C)","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false}]},{"clave":"despues","titulo":"DESPUÉS DE LA PRUEBA","puntos":[{"clave":"MB-P01","texto":"Registrar la hora de finalización de la prueba","tipo":"hora","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-P01O","texto":"Observaciones de la hora de finalización","tipo":"texto","obligatorio":false,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-P02","texto":"Registrar el número de horas de funcionamiento","tipo":"texto","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-P02O","texto":"Observaciones de las horas de funcionamiento","tipo":"texto","obligatorio":false,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-P03","texto":"Registrar la presión del sistema en el tablero de control principal","tipo":"texto","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-P03O","texto":"Observaciones de la presión del sistema","tipo":"texto","obligatorio":false,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-P04","texto":"Verificar la posición de los selectores de controladores principal y Jockey","tipo":"texto","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"MB-P04O","texto":"Observaciones de la posición de los selectores","tipo":"texto","obligatorio":false,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false}]}]}$j$::jsonb as receta)
